+++ public/r/counter.json	
@@ -0,0 +1,18 @@
+{
+  "$schema": "https://ui.shadcn.com/schema/registry-item.json",
+  "name": "counter",
+  "title": "Counter",
+  "description": "Animated counter that counts up to a value with easing when scrolled into view.",
+  "dependencies": [
+    "motion"
+  ],
+  "files": [
+    {
+      "path": "registry/new-york/counter.tsx",
+      "content": ""use client";

import type { Transition } from "motion/react";
import {
  animate,
  useInView,
  useMotionValue,
  useMotionValueEvent,
} from "motion/react";
import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

interface CounterProps {
  value: number;
  from?: number;
  duration?: number;
  delay?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  separator?: string;
  decimalSeparator?: string;
  transition?: Transition;
  trigger?: "inView" | "auto";
  className?: string;
  onComplete?: () => void;
}

const Counter = ({
  value,
  from = 0,
  duration = 2,
  delay = 0,
  decimals = 0,
  prefix = "",
  suffix = "",
  separator = ",",
  decimalSeparator = ".",
  transition,
  trigger = "inView",
  className,
  onComplete,
  ...props
}: CounterProps & React.HTMLAttributes<HTMLSpanElement>) => {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true, amount: 0.5 });
  const motionValue = useMotionValue(from);
  const [displayValue, setDisplayValue] = useState(from);

  useMotionValueEvent(motionValue, "change", (latest) => {
    setDisplayValue(latest);
  });

  useEffect(() => {
    if (trigger === "inView" && !inView) {
      return;
    }

    const controls = animate(motionValue, value, {
      ...transition,
      duration: transition?.duration ?? duration,
      delay,
      ease: transition?.ease ?? [0.16, 1, 0.3, 1],
      onComplete,
    });

    return () => controls.stop();
  }, [
    value,
    from,
    duration,
    delay,
    inView,
    trigger,
    transition,
    motionValue,
    onComplete,
  ]);

  const formatValue = (num: number) => {
    const fixed = num.toFixed(decimals);
    const [int, dec] = fixed.split(".");
    const formattedInt = int.replace(/\B(?=(\d{3})+(?!\d))/g, separator);
    return dec !== undefined
      ? `${formattedInt}${decimalSeparator}${dec}`
      : formattedInt;
  };

  return (
    <span ref={ref} className={cn("tabular-nums", className)} {...props}>
      <span className="sr-only">{`${prefix}${formatValue(value)}${suffix}`}</span>
      <span aria-hidden="true">
        {prefix}
        {formatValue(displayValue)}
        {suffix}
      </span>
    </span>
  );
};

export default Counter;
",
+      "type": "registry:ui",
+      "target": "components/prsui/counter.tsx"
+    }
+  ],
+  "type": "registry:ui"
+}
