+{
+  "$schema": "https://ui.shadcn.com/schema/registry-item.json",
+  "name": "morphing-text",
+  "title": "Morphing Text",
+  "description": "Text that cycles between words with a smooth blur-and-slide morph transition.",
+  "dependencies": [
+    "motion"
+  ],
+  "files": [
+    {
+      "path": "registry/new-york/morphing-text.tsx",
+      "content": ""use client";

import type { Variants } from "motion/react";
import { AnimatePresence, motion } from "motion/react";
import type { ElementType } from "react";
import { useEffect, useState } from "react";

import { cn } from "@/lib/utils";

interface MorphingTextProps {
  words: string[];
  interval?: number;
  pauseOnHover?: boolean;
  as?: ElementType;
  className?: string;
}

const morphVariants: Variants = {
  initial: { y: 12, opacity: 0, filter: "blur(12px)" },
  animate: {
    y: 0,
    opacity: 1,
    filter: "blur(0px)",
    transition: { duration: 0.5, ease: [0.16, 1, 0.3, 1] },
  },
  exit: {
    y: -12,
    opacity: 0,
    filter: "blur(12px)",
    transition: { duration: 0.3, ease: [0.77, 0, 0.175, 1] },
  },
};

const MorphingText = ({
  words,
  interval = 3000,
  pauseOnHover = false,
  as: Tag = "div",
  className,
  ...props
}: MorphingTextProps & React.HTMLAttributes<HTMLElement>) => {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (paused || words.length <= 1) {
      return;
    }

    const id = setInterval(() => {
      setIndex((prev) => (prev + 1) % words.length);
    }, interval);

    return () => clearInterval(id);
  }, [interval, paused, words.length]);

  return (
    <Tag
      className={cn("inline-flex overflow-hidden", className)}
      onMouseEnter={() => pauseOnHover && setPaused(true)}
      onMouseLeave={() => pauseOnHover && setPaused(false)}
      {...props}
    >
      <AnimatePresence mode="wait" initial={false}>
        <motion.span
          key={words[index]}
          variants={morphVariants}
          initial="initial"
          animate="animate"
          exit="exit"
          className="inline-block"
        >
          {words[index]}
        </motion.span>
      </AnimatePresence>
    </Tag>
  );
};

export default MorphingText;
",
+      "type": "registry:ui",
+      "target": "components/prsui/morphing-text.tsx"
+    }
+  ],
+  "type": "registry:ui"
+}
